class AdminDashboardComponent {
  projectService;
  userService;
  authService;
  router;
  route;
  projects = [];
  filteredProjects = [];
  selectedPlatform = 'all';
  currentView = 'home';
  viewMode = 'list'; // Added viewMode
  selectedProject = null;
  isDarkMode = false;
  availableManagers = []; // Users/Managers list
  // Modal & Navigation States
  showTaskModal = false;
  selectedStageId = '';
  currentSection = 'dashboard';
  // Project Creation
  showProjectCreationModal = false;
  selectedPlatformForCreation;
  // User Management
  showUserCreationModal = false;
  isEditingUser = false;
  newUser = {
    name: '',
    email: '',
    password: '',
    role: 'user'
  }; // Initialize for form binding
  // Filters
  searchQuery = '';
  selectedStatusFilter = 'all';
  currentUser = null;
  constructor(projectService, userService,
  // Keep UserService injected
  authService, router, route) {
    this.projectService = projectService;
    this.userService = userService;
    this.authService = authService;
    this.router = router;
    this.route = route;
  }
  ngOnInit() {
    this.authService.currentUser.subscribe(user => {
      this.currentUser = user ? user.user || user : null;
    });
    this.loadProjects();
    this.loadAvailableManagers();
    // Load Theme
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'dark') {
      this.isDarkMode = true;
      document.documentElement.classList.add('dark');
    } else {
      this.isDarkMode = false;
      document.documentElement.classList.remove('dark');
    }
    // Handle Query Params for Tabs
    this.route.queryParams.subscribe(params => {
      if (params['tab']) {
        const tab = params['tab'];
        if (['dashboard', 'projects', 'users', 'settings'].includes(tab)) {
          this.currentSection = tab;
        }
      }
    });
  }
  loadProjects() {
    this.projectService.getAllProjects().subscribe({
      next: projects => {
        this.projects = projects;
        this.filterProjects();
        // Refresh selectedProject if it exists
        if (this.selectedProject) {
          const updated = this.projects.find(p => p.id === this.selectedProject.id);
          if (updated) {
            this.selectedProject = updated;
          }
        }
      },
      error: error => console.error('Error loading projects:', error)
    });
  }
  loadAvailableManagers() {
    this.projectService.getAvailableManagers().subscribe({
      next: users => {
        this.availableManagers = users;
      },
      error: error => {
        console.error('Error loading managers:', error);
        this.availableManagers = [];
      }
    });
  }
  filterProjects() {
    let filtered = this.projects;
    // Filter by Platform
    if (this.selectedPlatform !== 'all') {
      filtered = filtered.filter(p => p.platform === this.selectedPlatform);
    }
    // Filter by Search Query
    if (this.searchQuery) {
      const query = this.searchQuery.toLowerCase();
      filtered = filtered.filter(p => p.name.toLowerCase().includes(query) || p.projectManager?.name?.toLowerCase().includes(query));
    }
    // Filter by Status
    if (this.selectedStatusFilter !== 'all') {
      filtered = filtered.filter(p => p.status === this.selectedStatusFilter);
    }
    this.filteredProjects = filtered;
  }
  navigateToProject(projectId) {
    console.log('Navigating to project:', projectId);
    this.router.navigate(['/projects', projectId]);
  }
  logout() {
    this.authService.logout();
    this.router.navigateByUrl('/auth/login');
  }
  // UI Helper Methods (Missing in original)
  getSectionNavClass(section) {
    const baseClass = 'w-full text-left px-4 py-2 rounded-lg transition-colors duration-200 flex items-center mb-1';
    const activeClass = 'bg-blue-50 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300 font-medium border-l-4 border-blue-600 dark:border-blue-400';
    const inactiveClass = 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800';
    return `${baseClass} ${this.currentSection === section ? activeClass : inactiveClass}`;
  }
  toggleDarkMode() {
    this.isDarkMode = !this.isDarkMode;
    if (this.isDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  }
  navigateToSection(section) {
    this.currentSection = section;
    if (section === 'projects') {
      // If navigating to projects tab manually, default to list view or keep current?
      // Let's default to list view for standard navigation
      this.viewMode = 'list';
      this.currentView = 'home'; // Show all by default
      this.filterProjects();
    }
    this.router.navigate([], {
      relativeTo: this.route,
      queryParams: {
        tab: section
      },
      queryParamsHandling: 'merge'
    });
  }
  navigateTo(view) {
    this.currentView = view;
    this.currentSection = 'projects'; // Switch to projects tab
    if (view === 'home') {
      this.viewMode = 'list';
      this.selectedPlatform = 'all';
    } else {
      this.viewMode = 'grid'; // Switch to grid view for specific platforms
      this.selectedPlatform = view;
    }
    this.filterProjects();
    this.selectedProject = null; // Reset selected project when changing view
    // Update URL tab
    this.router.navigate([], {
      relativeTo: this.route,
      queryParams: {
        tab: 'projects'
      },
      queryParamsHandling: 'merge'
    });
  }
  switchToGridView() {
    this.viewMode = 'grid';
  }
  switchToListView() {
    this.viewMode = 'list';
  }
  getNavClass(view) {
    const isActive = this.currentView === view;
    return isActive ? 'px-4 py-2 bg-blue-600 text-white rounded-lg shadow-sm' : 'px-4 py-2 bg-white dark:bg-gray-800 text-gray-700 dark:text-gray-200 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-700';
  }
  // Dashboard Stats
  getStats() {
    return {
      total: this.projects.length,
      completed: this.projects.filter(p => p.status === 'completed').length,
      inProgress: this.projects.filter(p => p.status === 'in_progress').length,
      lagging: this.projects.filter(p => p.status === 'lagging').length
    };
  }
  // Platform & Status Styling Helpers
  getPlatformDotClass(platform) {
    return platform === 'flame' ? 'w-3 h-3 rounded-full bg-orange-500' : 'w-3 h-3 rounded-full bg-blue-500';
  }
  getStatusBadgeClass(status) {
    const classes = {
      completed: 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300',
      in_progress: 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-300',
      at_risk: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-300',
      lagging: 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300',
      setup: 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-300'
    };
    return `px-2 py-1 rounded-full text-xs font-medium ${classes[status] || classes.setup}`;
  }
  getProgressBarClass(status) {
    switch (status) {
      case 'completed':
        return 'h-2 rounded-full bg-green-500';
      case 'lagging':
        return 'h-2 rounded-full bg-red-500';
      case 'at_risk':
        return 'h-2 rounded-full bg-yellow-500';
      default:
        return 'h-2 rounded-full bg-blue-500';
    }
  }
  getPlatformTextClass(view) {
    if (view === 'flame') return 'text-orange-600 dark:text-orange-400';
    if (view === 'swayam') return 'text-blue-600 dark:text-blue-400';
    return 'text-gray-800 dark:text-white';
  }
  getProjectItemClass(project) {
    const isSelected = this.selectedProject?.id === project.id;
    const baseClass = 'p-4 border-b dark:border-gray-700 cursor-pointer transition-colors';
    const activeClass = 'bg-blue-50 dark:bg-blue-900/20 border-l-4 border-l-blue-500';
    const inactiveClass = 'hover:bg-gray-50 dark:hover:bg-gray-700/50';
    return `${baseClass} ${isSelected ? activeClass : inactiveClass}`;
  }
  selectProject(project) {
    this.selectedProject = project;
  }
  // Project Creation Modal Handlers
  openProjectCreationModal(platform) {
    this.selectedPlatformForCreation = platform;
    this.showProjectCreationModal = true;
  }
  closeProjectCreationModal() {
    this.showProjectCreationModal = false;
  }
  onProjectCreated(project) {
    this.loadProjects();
    this.showProjectCreationModal = false;
  }
